CREATE DATABASE IF NOT EXISTS travel_agency_books CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE travel_agency_books;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, username VARCHAR(80) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','staff') NOT NULL DEFAULT 'staff', mobile VARCHAR(40) DEFAULT '', address VARCHAR(255) DEFAULT '', designation VARCHAR(100) DEFAULT '', salary DECIMAL(12,2) NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, phone VARCHAR(40), email VARCHAR(150), passport_no VARCHAR(80), nid_no VARCHAR(80), address VARCHAR(255), notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(name), INDEX(passport_no)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS suppliers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, type VARCHAR(80), phone VARCHAR(40), email VARCHAR(150), address VARCHAR(255), opening_balance DECIMAL(12,2) NOT NULL DEFAULT 0, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bookings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_no VARCHAR(40) UNIQUE NOT NULL, customer_id INT UNSIGNED NOT NULL, service_type ENUM('air_ticket','hotel','tour_package','visa','transport','insurance','other') NOT NULL, travel_date DATE NULL, return_date DATE NULL, destination VARCHAR(160), reference_no VARCHAR(100), status ENUM('quotation','confirmed','partially_paid','paid','completed','cancelled') NOT NULL DEFAULT 'quotation', sale_amount DECIMAL(12,2) NOT NULL DEFAULT 0, cost_amount DECIMAL(12,2) NOT NULL DEFAULT 0, paid_amount DECIMAL(12,2) NOT NULL DEFAULT 0, notes TEXT, created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL, INDEX(status), INDEX(travel_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, txn_date DATE NOT NULL, type ENUM('income','expense','collection','supplier_payment','refund','adjustment') NOT NULL, category VARCHAR(100) NOT NULL, amount DECIMAL(12,2) NOT NULL, customer_id INT UNSIGNED NULL, supplier_id INT UNSIGNED NULL, booking_id INT UNSIGNED NULL, payment_method ENUM('cash','bank','mobile_banking','card','other') NOT NULL DEFAULT 'cash', reference_no VARCHAR(100), description VARCHAR(255), created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL, FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL, INDEX(txn_date), INDEX(type)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS documents (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id INT UNSIGNED NOT NULL, doc_type ENUM('passport','visa','nid','ticket','other') NOT NULL, document_no VARCHAR(100), issue_date DATE NULL, expiry_date DATE NULL, status ENUM('active','expired','submitted','received') DEFAULT 'active', notes VARCHAR(255), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE, INDEX(expiry_date));
CREATE TABLE IF NOT EXISTS attendance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, work_date DATE NOT NULL, status ENUM('present','absent') NOT NULL DEFAULT 'present', UNIQUE KEY(user_id,work_date), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS salary_payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, pay_month CHAR(7) NOT NULL, days_present INT NOT NULL DEFAULT 0, amount DECIMAL(12,2) NOT NULL, paid_date DATE NOT NULL, notes VARCHAR(255), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, token_hash VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, used TINYINT(1) DEFAULT 0, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL);
